$Script:Lang='en'

function L($key){$set=$TX.PSObject.Properties[$Script:Lang].Value;$p=$set.PSObject.Properties[$key];if($p){return [string]$p.Value};return $key}
function Log($s){try{Add-Content $LogFile -Value ('[{0}] {1}'-f(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$s)-Encoding UTF8}catch{}}
function RegD($p,$n,$v){try{New-Item $p -Force|Out-Null;New-ItemProperty $p -Name $n -PropertyType DWord -Value $v -Force|Out-Null}catch{}}
function RegS($p,$n,$v){try{New-Item $p -Force|Out-Null;New-ItemProperty $p -Name $n -PropertyType String -Value $v -Force|Out-Null}catch{}}
function Snap($p,$n){$e=$false;$v=$null;$k='DWord';try{$i=Get-ItemProperty -LiteralPath $p -ErrorAction Stop;$x=$i.PSObject.Properties[$n];if($x){$e=$true;$v=$x.Value;if($v -is [string]){$k='String'}}}catch{};return [pscustomobject]@{Path=$p;Name=$n;Exists=$e;Value=$v;Kind=$k}}
function RestoreSnap($e){if($e.Exists){if($e.Kind -eq 'String'){RegS $e.Path $e.Name ([string]$e.Value)}else{RegD $e.Path $e.Name ([int64]$e.Value)}}else{Remove-ItemProperty -LiteralPath $e.Path -Name $e.Name -ErrorAction SilentlyContinue}}
function DiskInfo{$h=$false;$s=$false;try{foreach($d in @(Get-PhysicalDisk)){$m=[string]$d.MediaType;if($m -match 'HDD'){$h=$true};if($m -match 'SSD'){$s=$true}}}catch{};if(-not $h -and -not $s){try{foreach($d in @(Get-CimInstance Win32_DiskDrive)){$m=([string]$d.Model+' '+[string]$d.MediaType+' '+[string]$d.InterfaceType);if($m -match 'SSD|Solid State|NVMe'){$s=$true}elseif($m -match 'HDD|Hard Disk'){$h=$true}}}catch{}};return [pscustomobject]@{HDD=$h;SSD=$s}}
function Hardware{$c=Get-CimInstance Win32_Processor|Select-Object -First 1;$cs=Get-CimInstance Win32_ComputerSystem;$g=@(Get-CimInstance Win32_VideoController);$d=DiskInfo;$ram=0;if($cs){$ram=[math]::Round($cs.TotalPhysicalMemory/1GB,1)};$gpu='Unknown';foreach($x in $g){if($gpu -eq 'Unknown'){$gpu=[string]$x.Name}else{$gpu+=' | '+[string]$x.Name}};return [pscustomobject]@{CPU=if($c){[string]$c.Name}else{'Unknown'};Cores=if($c){[int]$c.NumberOfCores}else{0};Threads=if($c){[int]$c.NumberOfLogicalProcessors}else{0};RAM=$ram;GPU=$gpu;HDD=$d.HDD;SSD=$d.SSD;Virtualization=if($c){[bool]$c.VirtualizationFirmwareEnabled}else{$false}}}
function Recommendation($h){$c=4;$r=4;if($h.Threads -lt 4){$c=2};if($h.RAM -lt 8){$r=2};return [pscustomobject]@{Cores=$c;RAM=$r;Mode='High Performance';FPS='120 recommended / 240 ceiling optional';SysMain=if($h.HDD -or $h.RAM -le 8){'KEEP AUTO'}else{'OPTIONAL'}}}
function BlueStacksPath{foreach($p in @("$env:ProgramFiles\BlueStacks_nxt\HD-Player.exe","$env:ProgramFiles\BlueStacks_nxt5\HD-Player.exe","${env:ProgramFiles(x86)}\BlueStacks_nxt\HD-Player.exe","${env:ProgramFiles(x86)}\BlueStacks_nxt5\HD-Player.exe")){if($p -and(Test-Path $p)){return $p}};return $null}
function PendingReboot{$a=Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending';$b=Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired';return($a -or $b)}
function Conflicts{$list=New-Object System.Collections.ArrayList;$p=Get-Process -Name Discord -ErrorAction SilentlyContinue;if($p){$list.Add('Discord running')};$p=Get-Process -Name RivaTunerStatisticsServer -ErrorAction SilentlyContinue;if($p){$list.Add('RTSS running')};$s=Get-Service vmms -ErrorAction SilentlyContinue;if($s -and $s.Status -eq 'Running'){$list.Add('Hyper-V service running')};$s=Get-Service com.docker.service -ErrorAction SilentlyContinue;if($s -and $s.Status -eq 'Running'){$list.Add('Docker service running')};return $list}
function CreateBaseline{if(Test-Path $Pointer){$d=(Get-Content $Pointer -Raw -Encoding UTF8).Trim();if($d -and(Test-Path(Join-Path $d 'Baseline.xml'))){return $d}};$d=Join-Path $BackupRoot(Get-Date -Format 'yyyyMMdd_HHmmss');New-Item -ItemType Directory $d -Force|Out-Null;$st=[ordered]@{Created=(Get-Date).ToString('o');Power=((powercfg /getactivescheme)-join ' ');Registry=New-Object System.Collections.ArrayList;Services=New-Object System.Collections.ArrayList};foreach($x in @(@('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness'),@('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex'),@('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation'),@('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff'),@('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode'),@('HKLM:\SOFTWARE\Microsoft\Windows\Dwm','OverlayTestMode'),@('HKCU:\Software\Microsoft\GameBar','AutoGameModeEnabled'),@('HKCU:\System\GameConfigStore','GameDVR_Enabled'))){$st.Registry.Add((Snap $x[0] $x[1]))};try{$s=Get-CimInstance Win32_Service -Filter "Name='SysMain'";$st.Services.Add([pscustomobject]@{Name='SysMain';Start=[string]$s.StartMode;State=[string]$s.State})}catch{};$st|Export-Clixml(Join-Path $d 'Baseline.xml');powercfg /list|Out-File(Join-Path $d 'PowerPlans.txt')-Encoding UTF8;bcdedit /enum all|Out-File(Join-Path $d 'BCD.txt')-Encoding UTF8;Set-Content $Pointer $d -Encoding UTF8;Log('Baseline created: '+$d);return $d}
function EnsureBaseline{$null=CreateBaseline}
function RestoreBaseline{$d=$null;if(Test-Path $Pointer){$d=(Get-Content $Pointer -Raw -Encoding UTF8).Trim()};if(-not $d){[System.Windows.Forms.MessageBox]::Show('No KXM baseline found.','KXM // Restore')|Out-Null;return};$f=Join-Path $d 'Baseline.xml';if(-not(Test-Path $f)){return};$a=[System.Windows.Forms.MessageBox]::Show('Restore the settings captured BEFORE KXM?','KXM // Restore',[System.Windows.Forms.MessageBoxButtons]::YesNo,[System.Windows.Forms.MessageBoxIcon]::Warning);if($a -ne [System.Windows.Forms.DialogResult]::Yes){return};$st=Import-Clixml $f;foreach($e in $st.Registry){RestoreSnap $e};foreach($s in $st.Services){if($s.Start -eq 'Auto'){Set-Service $s.Name -StartupType Automatic}elseif($s.Start -eq 'Manual'){Set-Service $s.Name -StartupType Manual}elseif($s.Start -eq 'Disabled'){Set-Service $s.Name -StartupType Disabled};if($s.State -eq 'Running'){Start-Service $s.Name}else{if($s.State -eq 'Stopped'){Stop-Service $s.Name -Force}}};if($st.Power -match '([0-9a-fA-F-]{36})'){powercfg /setactive $Matches[1]|Out-Null};Log('Restore completed');[System.Windows.Forms.MessageBox]::Show('Restore completed. Reboot Windows.','KXM')|Out-Null}
function StartSession{$d=EnsureBaseline;if(Test-Path $SessionFile){return 'Session already active.'};$p=Get-Process -Name HD-Player -ErrorAction SilentlyContinue|Select-Object -First 1;$st=[ordered]@{Started=(Get-Date).ToString('o');Power=((powercfg /getactivescheme)-join ' ');Priority=if($p){[string]$p.PriorityClass}else{'Idle'}};$st|Export-Clixml $SessionFile;foreach($x in @($env:TEMP,(Join-Path $env:LOCALAPPDATA 'Temp'),'C:\Windows\Temp')){if(Test-Path $x){Remove-Item -LiteralPath(Join-Path $x '*')-Recurse -Force -ErrorAction SilentlyContinue}};ipconfig /flushdns|Out-Null;powercfg /setactive SCHEME_MIN|Out-Null;if($p){try{$p.PriorityClass='AboveNormal'}catch{}};Log('Session start');return 'GAME READY ACTIVE.`r`nTemp cleanup complete.`r`nDNS flushed.`r`nHigh Performance active.'}
function EndSession{if(-not(Test-Path $SessionFile)){return 'No active KXM gaming session.'};$s=Import-Clixml $SessionFile;if($s.Power-match'([0-9a-fA-F-]{36})'){powercfg /setactive $Matches[1]|Out-Null};Remove-Item $SessionFile -Force -ErrorAction SilentlyContinue;Log('Session end');return 'SESSION ENDED.`r`nOriginal power plan restored.'}
function SmartOptimize{EnsureBaseline;$h=Hardware;powercfg /setactive SCHEME_MIN|Out-Null;RegD 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' 1;RegD 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0;RegD 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 0;$mm='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile';$g="$mm\Tasks\Games";RegD $mm 'SystemResponsiveness' 0;RegD $mm 'NetworkThrottlingIndex' 4294967295;RegD $g 'GPU Priority' 8;RegD $g 'Priority' 6;RegD 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl' 'Win32PrioritySeparation' 38;RegD 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' 'PowerThrottlingOff' 1;$bs=BlueStacksPath;if($bs){RegS 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences' $bs 'GpuPreference=2;'};if($h.HDD -or $h.RAM -le 8){Set-Service SysMain -StartupType Automatic;Start-Service SysMain};Log('Smart optimize');return(Get-Recommendation $h)}

