$names=@('Hardware Audit','Game Profiles','Conflict Check','Before/After','Backup Center','Verify','Network','System Health','Reboot Status','Experimental');$i=0
foreach($name in $names){$b=New-Object System.Windows.Forms.Button;$b.Text=$name;$b.Tag=$name;$col=$i%5;$row=[math]::Floor($i/5);$b.Location=New-Object System.Drawing.Point((18+150*$col),(35+92*$row));$b.Size=New-Object System.Drawing.Size(138,65);$b.BackColor=[System.Drawing.Color]::FromArgb(27,34,44);$b.ForeColor=[System.Drawing.Color]::White;$b.FlatStyle='Flat';$b.Add_Click({$n=$this.Tag;$hh=Hardware;$rr=Recommendation $hh;if($n -eq 'Hardware Audit'){$details.Text=("CPU: {0}`r`nCores/Threads: {1}/{2}`r`nRAM: {3} GB`r`nGPU: {4}`r`nHDD: {5}  SSD: {6}`r`nVirtualization: {7}`r`nRecommendation: 4 cores / 4 GB / High Performance"-f$hh.CPU,$hh.Cores,$hh.Threads,$hh.RAM,$hh.GPU,$hh.HDD,$hh.SSD,$hh.Virtualization)}elseif($n -eq 'Game Profiles'){$details.Text='FREE FIRE / FREE FIRE MAX`r`n`r`nBlueStacks: 4 CPU cores`r`nBlueStacks: 4 GB RAM`r`nMode: High Performance`r`nFPS target: 120 recommended`r`n240 FPS: optional ceiling, not guaranteed'}elseif($n -eq 'Conflict Check'){$c=Conflicts;if($c.Count -eq 0){$details.Text='CONFLICT CHECK`r`n`r`nNo common conflicts detected.'}else{$details.Text='CONFLICT CHECK`r`n`r`n'+($c -join "`r`n")}}elseif($n -eq 'Before/After'){$file=Join-Path $Root 'LastBenchmark.xml';$snap=[ordered]@{Time=(Get-Date).ToString('o');CPU=$hh.CPU;RAM=$hh.RAM;GPU=$hh.GPU;CPULoad=(try{(Get-CimInstance Win32_Processor|Measure-Object LoadPercentage -Average).Average}catch{0});MemoryUsed=(MemUsed);Power=((powercfg /getactivescheme)-join ' ')};$old=$null;if(Test-Path $file){$old=Import-Clixml $file};$snap|Export-Clixml $file;if($old){$details.Text=("BEFORE / AFTER`r`n`r`nPrevious CPU Load: {0}`r`nCurrent CPU Load: {1}`r`nPrevious RAM Used: {2} GB`r`nCurrent RAM Used: {3} GB`r`n`r`nThis is a system snapshot; enter real in-game FPS separately."-f$old.CPULoad,$snap.CPULoad,$old.MemoryUsed,$snap.MemoryUsed)}else{$details.Text='BASELINE SNAPSHOT SAVED.`r`nRun this action again after testing to compare.'}}elseif($n -eq 'Backup Center'){$details.Text=('BASELINE: '+((CreateBaseline)))}elseif($n -eq 'Verify'){$details.Text=("Power: {0}`r`nSysMain: {1}`r`nHAGS: {2}`r`nPending reboot: {3}"-f((powercfg /getactivescheme)-join ' '),(Get-Service SysMain).StartType,(Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' -ErrorAction SilentlyContinue).HwSchMode,(PendingReboot))}elseif($n -eq 'Network'){NetOptimize;$details.Text='NETWORK PROFILE APPLIED.`r`nRSS enabled.`r`nTCP autotuning normal.'}elseif($n -eq 'System Health'){$free=(Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'");$details.Text=("SYSTEM HEALTH`r`n`r`nC: Free: {0:N1} GB`r`nPower: {1}`r`nReboot pending: {2}`r`nConflicts: {3}"-f($free.FreeSpace/1GB),((powercfg /getactivescheme)-join ' '),(PendingReboot),(Conflicts).Count)}elseif($n -eq 'Reboot Status'){$details.Text=('REBOOT REQUIRED: '+(PendingReboot))}else{$details.Text='Experimental settings remain opt-in.`r`nNo kernel/BCD change is performed from this button.'}});$tools.Controls.Add($b);$i++}

